// scene.rs의 일부. 입력·테이블 조작 규칙과 독립된 표시만 갱신한다.
struct CombatGeometry{ids:[usize;5],panels:Vec<Instance>,feed:Vec<Instance>,labels:Vec<Instance>,minimap:Vec<Instance>,dots:Vec<Instance>}
impl CombatGeometry{
 fn new(gpu:&mut Gpu,max:usize)->Result<Self>{let mut ids=[0;5];for(i,name)in["playerPanels","killFeed","unitLabels","minimap","miniDots"].iter().enumerate(){let mut m=geometry::mesh(name,geometry::quad(),vec![],i!=3,i==3);m.dynamic=true;if i==1{m.depth_test=false;}ids[i]=gpu.add_mesh(&m,if i==0{2}else if i==1||i==3{1}else{max*3})?;}Ok(Self{ids,panels:Vec::with_capacity(2),feed:Vec::with_capacity(1),labels:Vec::with_capacity(max*3),minimap:Vec::with_capacity(1),dots:Vec::with_capacity(max)})}
}
#[derive(Clone,Copy)]struct PanelPlacement{center:Vec3,width:f32,height:f32,rotation:Quat}
fn panel_placements(local_head:Vec3,rotation:Quat)->[PanelPlacement;2]{
 let mut towards=Vec3::new(local_head.x,0.0,local_head.z);if towards.length_squared()<1e-6{towards=Vec3::Z;}towards=towards.normalize();let right=Vec3::new(towards.z,0.0,-towards.x);let support=right.x.abs()*1.26+right.z.abs()*1.08;
 std::array::from_fn(|team|{let sign=if team==0{-1.0}else{1.0};let(mut width,mut center)=(0.66f32,Vec3::ZERO);
  for _ in 0..20{let height=width*640.0/480.0;let x=rotation*Vec3::X;let y=rotation*Vec3::Y;let side=(right.dot(x).abs()*width+right.dot(y).abs()*height)*0.5;let up=(x.y.abs()*width+y.y.abs()*height)*0.5;center=right*(sign*(support+0.18+side))+Vec3::Y*(TABLE+0.03+up);width=width.max(local_head.distance(center)*0.36);}
  let height=width*640.0/480.0;let x=rotation*Vec3::X;let y=rotation*Vec3::Y;let side=(right.dot(x).abs()*width+right.dot(y).abs()*height)*0.5;let up=(x.y.abs()*width+y.y.abs()*height)*0.5;center=right*(sign*(support+0.18+side))+Vec3::Y*(TABLE+0.03+up);PanelPlacement{center,width,height,rotation}
 })
}
fn panel_clearance(instance:&Instance,_team:usize)->(f32,f32){let model=Mat4::from_cols_array_2d(&instance.model);let center=model.w_axis.truncate();let outward=Vec3::new(center.x,0.0,center.z).normalize();let support=outward.x.abs()*1.26+outward.z.abs()*1.08;let mut side=f32::INFINITY;let mut bottom=f32::INFINITY;for x in[-0.5,0.5]{for y in[-0.5,0.5]{let p=model.transform_point3(Vec3::new(x,y,0.0));side=side.min(p.dot(outward)-support);bottom=bottom.min(p.y-TABLE);}}(side,bottom)}
fn seconds(ticks:u32)->u16{ticks.div_ceil(60).min(u16::MAX as u32)as u16}
fn insert_feed(feed:&mut[crate::hud::FeedEntry;3],entry:crate::hud::FeedEntry){for i in 0..3{if entry.tick>feed[i].tick{for j in(i+1..3).rev(){feed[j]=feed[j-1];}feed[i]=entry;break;}}}
impl Scene{
 pub fn hud_pose(&self)->(Vec3,Quat){(self.hud_position,self.hud_rotation)}
 pub fn combat_feed_audit(&self)->[crate::hud::FeedEntry;3]{self.combat_content().feed}
 pub fn combat_panel_model(&self,team:usize)->Option<Mat4>{self.combat.panels.get(team).map(|i|self.world()*Mat4::from_cols_array_2d(&i.model))}
 pub fn combat_minimap_model(&self)->Option<Mat4>{self.combat.minimap.first().map(|i|self.world()*Mat4::from_cols_array_2d(&i.model))}
 pub fn combat_audit(&self,head:Vec3)->serde_json::Value{let angles:Vec<_>=self.combat.panels.iter().map(|i|{let world=self.world()*Mat4::from_cols_array_2d(&i.model);let(s,_,p)=world.to_scale_rotation_translation();let distance=p.distance(head);(2.0*((s.x*24.0/480.0)/(2.0*distance)).atan()).to_degrees()}).collect();serde_json::json!({"content":self.combat_content(),"panelInstances":self.combat.panels.len(),"feedInstances":self.combat.feed.len(),"labelInstances":self.combat.labels.len(),"mapInstances":self.combat.minimap.len(),"dotInstances":self.combat.dots.len(),"nominalPanelFontDegrees":angles,"panelClearanceMeters":self.combat.panels.iter().enumerate().map(|(t,i)|panel_clearance(i,t)).collect::<Vec<_>>(),"minimapFrontClearanceMeters":1.50-0.68/2.0-1.08,"feedWidthLogicalPixels":self.combat_content().feed_width,"metricFont40Degrees":({let center=self.hud_position+self.hud_rotation*Vec3::new(0.0,(160.0-190.0)/1024.0*self.hud_scale,0.0);let half=self.hud_rotation*Vec3::Y*(40.0/1024.0*self.hud_scale*0.5);(center+half-head).angle_between(center-half-head).to_degrees()}),"overheadLODdistanceMeters":2.2,"itemSetCount":self.assets.combat_item_sets.len()})}
 fn combat_content(&self)->crate::hud::CombatContent{
  use crate::hud::{CombatContent,PlayerCard,FeedEntry};let frame=self.source.frame(self.time.floor()as u32);let Some(ui)=&frame.ui else{return CombatContent::default();};let mut content=CombatContent{available:true,flags:self.ui.flags(),kill_diff:ui.score_diff[0],..Default::default()};let mut gold=[0i64;2];
  for p in &ui.players{if p.2>=2||p.3>=5{continue;}let(team,lane)=(p.2 as usize,p.3 as usize);gold[team]+=p.5 as i64;let entity=frame.entities.iter().find(|e|e.0==p.1);let hp=entity.map(|e|e.3).unwrap_or(0.0);let shield=entity.map(|e|e.8).unwrap_or(0.0);let max=entity.map(|e|e.4+shield).unwrap_or(1.0).max(1.0);content.players[team][lane]=PlayerCard{cooldown_mask:self.assets.combat_cooldown_masks[team][lane],hp:(hp/max*1000.0).clamp(0.0,1000.0)as u16,shield:(shield/max*1000.0).clamp(0.0,1000.0)as u16,level:p.4.min(u16::MAX as u32)as u16,alive:p.6!=0,respawn:seconds(p.7),k:p.8.min(u16::MAX as u32)as u16,d:p.9.min(u16::MAX as u32)as u16,a:p.10.min(u16::MAX as u32)as u16,cooldowns:[seconds(p.13),seconds(p.14),seconds(p.15)],items:self.assets.combat_item_sets.get(&p.11).copied().unwrap_or([0;6])};}
  content.gold_diff=(gold[0]-gold[1]).clamp(i32::MIN as i64,i32::MAX as i64)as i32;for e in &frame.entities{if e.alive()&&(0..2).contains(&e.5)&&self.source.manifest().catalog[&e.0].kind=="tower"{content.towers[e.5 as usize]=content.towers[e.5 as usize].saturating_add(1);}}
  if self.ui.kill_log{for k in self.source.recent_kills(frame.tick){if k.1>=2||k.2>=5||k.3>=5{continue;}let assists=k.4.iter().filter(|&&lane|lane<5).fold(0u8,|mask,&lane|mask|(1<<lane));insert_feed(&mut content.feed,FeedEntry{tick:k.0,kind:0,team:k.1 as i8,killer:k.2 as u8,victim:k.3 as u8,assists});}}
  if self.ui.events{for e in self.source.recent_objectives(frame.tick){let kind=match e.2.as_str(){"tower"=>1,"nexus"=>2,"serpen_monster"=>3,"epic_monster"=>4,_=>5};insert_feed(&mut content.feed,FeedEntry{tick:e.0,kind,team:e.3 as i8,..Default::default()});}}
  content.feed_width=content.feed.iter().filter(|e|e.tick>0).map(|e|{if e.kind==0{if e.assists==0{198}else{(326+62*e.assists.count_ones()).min(640)as u16}}else{let text=match e.kind{1=>"타워 파괴",2=>"넥서스 파괴",3=>"세르펜 제거",4=>"모르가드 제거",_=>"정글 목표 제거"};(40+text.chars().count()*32+if e.team>=0{3*32}else{0}).min(640)as u16}}).max().unwrap_or(0);
  content
 }
 fn update_combat_geometry(&mut self,gpu:&mut Gpu,head:Vec3,rotation:Quat)->Result<()>{
  let frame=self.source.frame(self.time.floor()as u32);let available=frame.ui.is_some();let world=self.world();let local_head=world.inverse().transform_point3(head);let local_rotation=Quat::from_rotation_y(-self.table_yaw)*rotation;
  let c=&mut self.combat;c.panels.clear();c.feed.clear();c.labels.clear();c.minimap.clear();c.dots.clear();
  if available&&self.show_hud&&self.ui.player_panels{for(team,p)in panel_placements(local_head,local_rotation).into_iter().enumerate(){let model=Mat4::from_scale_rotation_translation(Vec3::new(p.width,p.height,1.0),p.rotation,p.center);c.panels.push(Instance::new(model,crate::hud::atlas_uv(if team==0{0.0}else{544.0},320.0,480.0,640.0),[1.0;4],[10.0,0.001,0.0,0.0]));}}
  let content=self.combat_content();let c=&mut self.combat;
  if available&&self.show_hud&&content.feed[0].tick!=0{let rows=content.feed.iter().filter(|e|e.tick>0).count()as f32;let height=rows*64.0*0.001;let width=content.feed_width as f32*0.001;let center=self.hud_position+self.hud_rotation*Vec3::new(0.0,self.hud_scale*0.15625+0.020+height*0.5,0.0);let model=world.inverse()*Mat4::from_scale_rotation_translation(Vec3::new(width,height,1.0),self.hud_rotation,center);c.feed.push(Instance::new(model,crate::hud::atlas_uv(0.0,960.0,content.feed_width as f32,rows*64.0),[1.0;4],[10.0,0.001,0.0,0.0]));}
  if available&&self.show_hud&&self.ui.overhead{for(i,row)in self.rows.iter().enumerate(){if !row.alive()||self.source.manifest().catalog[&row.0].kind!="champion"{continue;}let model=Mat4::from_cols_array_2d(&self.units[i].model);let position=model.transform_point3(Vec3::new(0.0,0.5,0.0))+Vec3::new(0.0,0.019,0.0);let distance=world.transform_point3(position).distance(head);if distance>2.2{continue;}let height=(distance*0.035/self.table_scale).max(0.020);if row.7<=20{let center=position+local_rotation*Vec3::new(-0.035,height*0.5,0.001);let glyph=Mat4::from_scale_rotation_translation(Vec3::new(height*40.0/48.0,height,1.0),local_rotation,center);c.labels.push(Instance::new(glyph,crate::hud::atlas_uv(row.7 as f32*40.0,1152.0,40.0,48.0),[1.0;4],[10.0,0.001,0.0,0.0]));}if let Some(ui)=&frame.ui{for(j,cc)in ui.cc.iter().filter(|v|v.0==row.0&&v.1<10).take(2).enumerate(){let center=position+local_rotation*Vec3::new(0.020,height*(0.5+j as f32),0.002);let glyph=Mat4::from_scale_rotation_translation(Vec3::new(height*2.0,height,1.0),local_rotation,center);c.labels.push(Instance::new(glyph,crate::hud::atlas_uv(cc.1 as f32*96.0,1216.0,96.0,48.0),[1.0;4],[10.0,0.001,0.0,0.0]));}}}}
  if available&&self.ui.minimap{let base=&self.assets.meshes[0].instances[0];let center=Vec3::new(0.0,TABLE+0.080,1.50);let map=Mat4::from_scale_rotation_translation(Vec3::new(0.8,0.68,1.0),Quat::from_rotation_x(-std::f32::consts::FRAC_PI_2),center);c.minimap.push(Instance::new(map,base.uv,[1.0;4],base.params));for row in &frame.entities{if !row.alive(){continue;}let x=((row.1*0.001-480.0)*PIXEL as f64)as f32;let z=((row.2*0.001-480.0)*PIXEL as f64)as f32;let point=center+Vec3::new(x/2.4*0.8,0.001,z/2.04*0.68);let radius=if self.source.manifest().catalog[&row.0].kind=="champion"{0.012}else{0.007};let model=Mat4::from_scale_rotation_translation(Vec3::new(radius,radius,1.0),Quat::from_rotation_x(-std::f32::consts::FRAC_PI_2),point);let color=geometry::color_hex(match row.5{0=>0x9bd3ef,1=>0xe9a4a0,_=>0xafd88f},1.0);c.dots.push(Instance::new(model,[0.0;4],color,[2.0,0.0,0.0,0.0]));}}
  for(id,instances)in c.ids.into_iter().zip([&c.panels,&c.feed,&c.labels,&c.minimap,&c.dots]){gpu.update(id,instances)?;}Ok(())
 }
}
#[cfg(test)]mod combat_tests{use super::*;#[test]fn respawn_ticks_round_up_and_feed_keeps_latest(){assert_eq!(seconds(0),0);assert_eq!(seconds(1),1);assert_eq!(seconds(60),1);assert_eq!(seconds(61),2);let mut feed=[crate::hud::FeedEntry::default();3];for tick in[10,40,20,30]{insert_feed(&mut feed,crate::hud::FeedEntry{tick,..Default::default()});}assert_eq!(feed.map(|f|f.tick),[40,30,20]);}}

#[cfg(test)]mod layout_tests{use super::*;#[test]fn panels_stay_outside_table_and_above_top_for_all_views_and_scales(){for scale in[0.5,1.0,1.8,3.0]{for az in[-180f32,-120.0,-60.0,0.0,60.0,120.0,180.0]{for height in[0.3,1.1,1.7]{let az=az.to_radians();let head=Vec3::new(az.sin()*1.4/scale,TABLE+(height-TABLE)/scale,az.cos()*1.4/scale);let rotation=Mat4::look_at_rh(head,Vec3::new(0.0,TABLE,0.0),Vec3::Y).inverse().to_scale_rotation_translation().1;for(team,p)in panel_placements(head,rotation).into_iter().enumerate(){assert!((p.rotation*Vec3::Z).dot(rotation*Vec3::Z)>0.9999);let i=Instance::new(Mat4::from_scale_rotation_translation(Vec3::new(p.width,p.height,1.0),p.rotation,p.center),[0.0;4],[1.0;4],[0.0;4]);let(side,bottom)=panel_clearance(&i,team);assert!(side>=0.1799&&bottom>=0.0299);assert!(p.width.is_finite()&&p.height.is_finite());let angle=(2.0*((p.width*24.0/480.0)/(2.0*head.distance(p.center))).atan()).to_degrees();assert!(angle>=1.0);}}}}}}
